function clean(s: string): string {
  return s
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, "-")
    .replace(/…/g, "...");
}


// ------------------------------------------------------------------ canvas
const px = new Uint8Array(W * H * 3);
for (let i = 0; i < W * H; i++) {
  px[i * 3] = PAPER[0];
  px[i * 3 + 1] = PAPER[1];
  px[i * 3 + 2] = PAPER[2];
}

function dot(x: number, y: number, c: RGB): void {
  if (x < 0 || x >= W || y < 0 || y >= H) return;
  const i = (y * W + x) * 3;
  px[i] = c[0];
  px[i + 1] = c[1];
  px[i + 2] = c[2];
}
function box(x: number, y: number, w: number, h: number, c: RGB): void {
  for (let yy = y; yy < y + h; yy++)
    for (let xx = x; xx < x + w; xx++) dot(xx, yy, c);
}
function hline(x: number, y: number, w: number, c: RGB): void {
  box(x, y, w, 1, c);
}
function vline(x: number, y: number, h: number, c: RGB): void {
  box(x, y, 1, h, c);
}
// Bresenham line with a square brush of thickness t.
function seg(x0: number, y0: number, x1: number, y1: number, c: RGB, t = 1): void {
  const dx = Math.abs(x1 - x0);
  const dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  let x = x0;
  let y = y0;
  for (let guard = 0; guard < 6000; guard++) {
    box(x - Math.floor(t / 2), y - Math.floor(t / 2), t, t, c);
    if (x === x1 && y === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      x += sx;
    }
    if (e2 <= dx) {
      err += dx;
      y += sy;
    }
  }
}
function disc(cx: number, cy: number, r: number, c: RGB): void {
  for (let yy = cy - r; yy <= cy + r; yy++)
    for (let xx = cx - r; xx <= cx + r; xx++)
      if ((xx - cx) * (xx - cx) + (yy - cy) * (yy - cy) <= r * r) dot(xx, yy, c);
}
function ring(cx: number, cy: number, r: number, c: RGB): void {
  for (let a = 0; a < 360; a += 3) {
    const rad = (a * Math.PI) / 180;
    dot(Math.round(cx + r * Math.cos(rad)), Math.round(cy + r * Math.sin(rad)), c);
  }
}
// Scanline fill for a simple polygon given as [x, y] pairs.
function poly(pts: [number, number][], c: RGB): void {
  let minY = H;
  let maxY = 0;
  for (const [, y] of pts) {
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  for (let y = minY; y <= maxY; y++) {
    const xs: number[] = [];
    for (let i = 0; i < pts.length; i++) {
      const [x0, y0] = pts[i];
      const [x1, y1] = pts[(i + 1) % pts.length];
      if ((y0 <= y && y1 > y) || (y1 <= y && y0 > y)) {
        xs.push(Math.round(x0 + ((y - y0) * (x1 - x0)) / (y1 - y0)));
      }
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k + 1 < xs.length; k += 2) hline(xs[k], y, xs[k + 1] - xs[k], c);
  }
}
// Ellipse outline, used for the globe and the map land test.
function ellipse(cx: number, cy: number, rx: number, ry: number, c: RGB): void {
  for (let a = 0; a < 360; a += 2) {
    const rad = (a * Math.PI) / 180;
    dot(Math.round(cx + rx * Math.cos(rad)), Math.round(cy + ry * Math.sin(rad)), c);
  }
}
function inEllipse(x: number, y: number, cx: number, cy: number, rx: number, ry: number): boolean {
  const dx = (x - cx) / rx;
  const dy = (y - cy) / ry;
  return dx * dx + dy * dy <= 1;
}
// Fixed-seed generator (deterministic) for star / speckle placement.
function lcg(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

// -------------------------------------------------------------------- text
// Vector text: glyphs are real DejaVu outlines (see the font data above),
// filled with a 3x-supersampled scanline rasterizer, so letters have smooth
// anti-aliased curves like normal newspaper type — no pixel blocks.
// y = top of the cap-height line (as the old bitmap cells did); x = left.
// em size per legacy scale s: em = 9*s px (cap height 0.729em matches the
// old 7*s cell height). Serif = masthead + headlines; sans = everything else.
const SS = 3; // supersampling factor per axis
const CAP = 1493 / 2048; // DejaVu cap height, in em units
function emOf(s: number): number {
  return 9 * s;
}
function faceFor(serif: boolean, bold: boolean): FontFace {
  if (serif) return SERIF_BOLD;
  return bold ? SANS_BOLD : SANS;
}
function glyphOf(face: FontFace, ch: string): [number, number[][]] {
  return face.glyphs[ch] ?? face.glyphs["?"];
}
function charWpx(face: FontFace, ch: string, em: number): number {
  return (glyphOf(face, ch)[0] * em) / face.upm;
}
function strW(t: string, s: number, serif = false, bold = false): number {
  const em = emOf(s);
  const face = faceFor(serif, bold);
  let w = 0;
  for (const ch of clean(t)) w += charWpx(face, ch, em);
  return Math.round(w);
}
// Fill one glyph's outlines (even-odd rule) into the canvas with
// supersampled coverage, blended over whatever is already there.
function drawGlyph(face: FontFace, ch: string, x: number, baselineY: number, em: number, col: RGB): void {
  const glyph = glyphOf(face, ch);
  const contours = glyph[1];
  if (contours.length === 0) return;
  const scale = em / face.upm;
  const polys: number[][] = [];
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (const con of contours) {
    const p: number[] = new Array(con.length);
    for (let i = 0; i < con.length; i += 2) {
      const sx = x + con[i] * scale;
      const sy = baselineY - con[i + 1] * scale;
      p[i] = sx;
      p[i + 1] = sy;
      if (sx < minX) minX = sx;
      if (sx > maxX) maxX = sx;
      if (sy < minY) minY = sy;
      if (sy > maxY) maxY = sy;
    }
    polys.push(p);
  }
  const bx0 = Math.floor(minX);
  const bx1 = Math.ceil(maxX);
  const by0 = Math.floor(minY);
  const by1 = Math.ceil(maxY);
  const bw = Math.max(1, bx1 - bx0);
  const bh = Math.max(1, by1 - by0);
  const cov = new Uint8Array(bw * bh);
  const r0 = Math.floor(minY * SS);
  const r1 = Math.ceil(maxY * SS);
  for (let r = r0; r < r1; r++) {
    const yc = (r + 0.5) / SS;
    const oy = Math.floor(r / SS);
    if (oy < by0 || oy >= by1) continue;
    const xs: number[] = [];
    for (const p of polys) {
      const n = p.length / 2;
      for (let i = 0; i < n; i++) {
        const x0 = p[i * 2];
        const y0 = p[i * 2 + 1];
        const j = (i + 1) % n;
        const x1 = p[j * 2];
        const y1 = p[j * 2 + 1];
        if ((y0 <= yc && y1 > yc) || (y1 <= yc && y0 > yc)) {
          xs.push(x0 + ((yc - y0) * (x1 - x0)) / (y1 - y0));
        }
      }
    }
    xs.sort((a, b) => a - b);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const c0 = Math.ceil(xs[k] * SS - 0.5);
      const c1 = Math.ceil(xs[k + 1] * SS - 0.5);
      for (let cc = c0; cc < c1; cc++) {
        const ox = Math.floor(cc / SS);
        if (ox >= bx0 && ox < bx1) cov[(oy - by0) * bw + (ox - bx0)]++;
      }
    }
  }
  const maxCov = SS * SS;
  for (let yy = 0; yy < bh; yy++) {
    for (let xx = 0; xx < bw; xx++) {
      const cv = cov[yy * bw + xx];
      if (cv === 0) continue;
      const px2 = bx0 + xx;
      const py2 = by0 + yy;
      if (px2 < 0 || px2 >= W || py2 < 0 || py2 >= H) continue;
      const a = cv / maxCov;
      const idx = (py2 * W + px2) * 3;
      px[idx] = Math.round(col[0] * a + px[idx] * (1 - a));
      px[idx + 1] = Math.round(col[1] * a + px[idx + 1] * (1 - a));
      px[idx + 2] = Math.round(col[2] * a + px[idx + 2] * (1 - a));
    }
  }
}
function drawStr(t: string, x: number, y: number, s: number, c: RGB = INK, bold = false, serif = false): void {
  const em = emOf(s);
  const face = faceFor(serif, bold);
  const baselineY = y + CAP * em;
  let cx = x;
  for (const ch of clean(t)) {
    drawGlyph(face, ch, cx, baselineY, em, c);
    cx += charWpx(face, ch, em);
  }
}
function drawCentred(t: string, y: number, s: number, c: RGB = INK, bold = false, serif = false): void {
  drawStr(t, Math.round((W - strW(t, s, serif, bold)) / 2), y, s, c, bold, serif);
}
function wrapByWidth(t: string, s: number, maxW: number, serif = false, bold = false): string[] {
  const words = clean(t).split(" ");
  const lines: string[] = [];
  let cur = "";
  for (const w of words) {
    if (cur === "") cur = w;
    else if (strW(cur + " " + w, s, serif, bold) <= maxW) cur += " " + w;
    else {
      lines.push(cur);
      cur = w;
    }
  }
  if (cur !== "") lines.push(cur);
  return lines;
}

